{
  "key": "pr-1155",
  "fields": {
    "summary": "chore(factory): runners parent agent packs from the registry, not the git checkout",
    "description": "Mirror of the dmd shape: parent '<agent>@latest' (resolved from the\ndmtools-agents release registry via DMTOOLS_PACK_REGISTRY) and\npack:instruction refs instead of ../../factory-agents file paths and\nthe flat cliCommands/cliPrompts/JS-action list the pack parent chain\nalready carries. Owner mandate 2026-10-01: fa consumes dmtools-agents\nfrom releases, not checkouts."
  }
}

