                  ]
                }
              }
            }
          },
          "issueCounts": {
            "type": "object",
            "required": [
              "blocking",
              "important",
              "suggestion"
            ],
            "properties": {
              "blocking": {
                "type": "integer"
              },
              "important": {
                "type": "integer"
              },
              "suggestion": {
                "type": "integer"
              }
            }
          }
        }
      }
