        ],
        "properties": {
          "recommendation": {
            "type": "string",
            "enum": [
              "APPROVE",
              "REQUEST_CHANGES",
              "BLOCK"
            ]
          },
          "summary": {
            "type": "string"
          },
          "generalComment": {
            "type": "string"
          },
          "resolvedThreadIds": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "inlineComments": {
            "type": "array",
            "items": {
              "type": "object",
              "required": [
                "path",
                "line",
                "comment",
                "severity"
              ],
              "properties": {
                "path": {
                  "type": "string"
                },
                "line": {
                  "type": "integer"
                },
                "startLine": {
                  "type": [
                    "integer",
                    "null"
                  ]
